using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
namespace JuntosSomosMais.Utils.SimpleHistory.MongoDb;

/// <summary>
/// One row of a history collection. The element names are pinned, so a consumer's naming convention (e.g. camelCase)
/// never changes them: the purger, the indexes and every reader rely on these names.
/// </summary>
[BsonIgnoreExtraElements]
public class HistoryEntry
{
    /// <summary>Generated by the worker; not an ordering key (use <see cref="ChangeToken"/>).</summary>
    [BsonId]
    public ObjectId Id { get; set; } = ObjectId.GenerateNewId();

    /// <summary>The tracked document's <c>_id</c>, of any BSON type.</summary>
    [BsonElement(nameof(EntityId))]
    public BsonValue EntityId { get; set; } = BsonNull.Value;

    /// <summary>change.WallTime ?? ClusterTime (1 s resolution), UTC.</summary>
    [BsonElement(nameof(HistoryDate))]
    public DateTime HistoryDate { get; set; }

    /// <summary>One of <see cref="HistoryTypes"/>.</summary>
    [BsonElement(nameof(HistoryType))]
    public string HistoryType { get; set; } = HistoryTypes.Changed;

    /// <summary>
    /// "+" / "=" / "-": the full document without _id (only the tracked fields when <c>TrackedFields</c> is set).
    /// "~": the changed top-level fields with their new values, or the whole document when <see cref="ChangedFields"/>
    /// is present.
    /// </summary>
    [BsonElement(nameof(Data))]
    public BsonDocument Data { get; set; } = new();

    /// <summary>"~" only: top-level fields that no longer exist.</summary>
    [BsonElement(nameof(RemovedFields))]
    [BsonIgnoreIfNull]
    public List<string>? RemovedFields { get; set; }

    /// <summary>
    /// Full-document mode only: the top-level fields whose value changed. Its presence on a "~" row means
    /// <see cref="Data"/> is the whole document, not a delta.
    /// </summary>
    [BsonElement(nameof(ChangedFields))]
    [BsonIgnoreIfNull]
    public List<string>? ChangedFields { get; set; }

    /// <summary>
    /// Resume-token <c>_data</c> string: the position of the change in the oplog. Unique (makes inserts idempotent)
    /// and the ordering tiebreaker for equal <see cref="HistoryDate"/>.
    /// </summary>
    [BsonElement(nameof(ChangeToken))]
    public string ChangeToken { get; set; } = "";
}
